14	const distinct = (cells: Cell[]): Cell[] =>
15	  [...new Map(cells.map((cell) => [keyOf(cell), cell])).values()];
16	
17	export function nextGeneration(cells: Cell[]): Cell[] {
18	  const livingKeys = new Set(cells.map(keyOf));
19	
20	  const isAlive = (cell: Cell): boolean => livingKeys.has(keyOf(cell));
21	
22	  const countLiveNeighbours = (cell: Cell): number =>
23	    neighboursOf(cell).filter(isAlive).length;
24	
25	  const survives = (cell: Cell): boolean =>
26	    [2, 3].includes(countLiveNeighbours(cell));
27	
