31	    expect(sorted(next)).toEqual(sorted([[0, 0], [1, 0], [0, 1], [1, 1]]));
32	  });
33	  it("oscillates a vertical blinker to horizontal — [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]", () => {
34	    const next = nextGeneration([[0, 0], [0, 1], [0, 2]]);
35	    expect(sorted(next)).toEqual(sorted([[-1, 1], [0, 1], [1, 1]]));
36	  });
37	  it("oscillates a horizontal blinker back to vertical — [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]", () => {
38	    const next = nextGeneration([[-1, 1], [0, 1], [1, 1]]);
39	    expect(sorted(next)).toEqual(sorted([[0, 0], [0, 1], [0, 2]]));
40	  });
41	  it("handles negative coordinates — [(-1,-1), (-2,-1), (-3,-1)] → [(-2,-2), (-2,-1), (-2,0)]", () => {
42	    const next = nextGeneration([[-1, -1], [-2, -1], [-3, -1]]);
43	    expect(sorted(next)).toEqual(sorted([[-2, -2], [-2, -1], [-2, 0]]));
44	  });
45	});
